assignments.value:
={{
  (
    Number($('Create Finance Event').item.json.data.amountDue) >= 10000 ? 3 :
    Number($('Create Finance Event').item.json.data.amountDue) >= 5000 ? 2 :
    0
  )
  +
  (
    $('Create Finance Event').item.json.data.accountTier === 'enterprise' ? 2 : 0
  )
  +
  (
    Number($('Create Finance Event').item.json.data.paymentTermsDays) === 60 ? 1 : 0
  )
}}

